java.code:
public class Fibonacci {
    public long fib(int n) {
        if (n <= 1) return n;
        long a = 0, b = 1;
        for (int i = 2; i <= n; i++) { long c = a + b; a = b; b = c; }
        return b;
    }
    public static void main(String[] args) {
        Fibonacci f = new Fibonacci();
        for (int i = 0; i <= 10; i++) System.out.print(f.fib(i) + " ");
    }
}

